-- Source-backed workflow for native216 time changes and punch corrections. Prior migrations stay unchanged.
CREATE TABLE ty_tw_execution(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 subject_type text NOT NULL CHECK(subject_type IN('time_change','time_punch_correction')),subject_id bigint NOT NULL,instance_id bigint NOT NULL UNIQUE REFERENCES ty_workflow_instance(id),
 source_hash text NOT NULL,source_revision integer NOT NULL,outcome boolean NOT NULL,
 original_created_by bigint NOT NULL REFERENCES sys_account(id),submitted_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint NOT NULL REFERENCES sys_account(id),executed_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(subject_type,subject_id)
);
CREATE TRIGGER ty_tw_execution_keep BEFORE UPDATE OR DELETE ON ty_tw_execution FOR EACH ROW EXECUTE FUNCTION fn_ty_wf_append_only();
CREATE FUNCTION fn_ty_tw_source_hash(p_type text,p_id bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''SET timezone='UTC'AS $$
DECLARE r jsonb;deps jsonb;seg text;plan_key bigint;
BEGIN
 IF p_type='time_change'THEN
  SELECT to_jsonb(x) INTO r FROM public.ty_time_change_request x WHERE id=p_id;
  IF r IS NULL THEN RETURN NULL;END IF;plan_key:=(r->>'plan_id')::bigint;
  SELECT jsonb_build_object('plan',to_jsonb(p),'segments',(SELECT jsonb_agg(to_jsonb(s)ORDER BY s.id)FROM public.ty_time_plan_segment s WHERE s.id IN(SELECT(x->>'segment_id')::bigint FROM jsonb_array_elements(r->'patches')x)),
   'consents',(SELECT jsonb_agg(to_jsonb(c)ORDER BY c.person_id)FROM public.ty_time_change_consent c WHERE c.request_id=p_id),
   'employments',(SELECT jsonb_agg(to_jsonb(e)ORDER BY e.id)FROM public.ty_employment e WHERE e.id IN(SELECT(x->>'employment_id')::bigint FROM jsonb_array_elements(r->'patches')x UNION SELECT(x->>'employment_id')::bigint FROM jsonb_array_elements(r->'before_data')x)))INTO deps FROM public.ty_time_plan_version p WHERE p.id=plan_key;
 ELSIF p_type='time_punch_correction'THEN
  SELECT to_jsonb(x)INTO r FROM public.ty_time_punch_correction_request x WHERE id=p_id;IF r IS NULL THEN RETURN NULL;END IF;seg:=r->>'segment_ref';
  IF seg LIKE'plan:%'THEN SELECT jsonb_build_object('segment',to_jsonb(s),'plan',to_jsonb(p))INTO deps FROM public.ty_time_plan_segment s JOIN public.ty_time_plan_version p ON p.id=s.plan_id WHERE s.id=substring(seg FROM 6)::bigint;
  ELSE SELECT jsonb_build_object('segment',to_jsonb(s),'day',to_jsonb(d),'period',to_jsonb(p))INTO deps FROM public.ty_roster_segment s JOIN public.ty_roster_day d ON d.id=s.day_id JOIN public.ty_roster_period p ON p.id=d.period_id WHERE s.id=substring(seg FROM 6)::bigint;END IF;
  deps:=deps||jsonb_build_object('raw_punches',(SELECT jsonb_agg(to_jsonb(p)ORDER BY p.id)FROM public.ty_time_raw_punch p WHERE p.employment_id=(r->>'employment_id')::bigint AND p.punched_at>=((coalesce((deps->'segment'->>'work_date')::date,(deps->'day'->>'work_date')::date)-1)::timestamp AT TIME ZONE 'Asia/Shanghai')AND p.punched_at<((coalesce((deps->'segment'->>'work_date')::date,(deps->'day'->>'work_date')::date)+2)::timestamp AT TIME ZONE 'Asia/Shanghai')));
  deps:=deps||jsonb_build_object('employment',(SELECT to_jsonb(e)FROM public.ty_employment e WHERE e.id=(r->>'employment_id')::bigint),'current_reports',(SELECT jsonb_agg(to_jsonb(h)ORDER BY h.id)FROM public.ty_time_report_root h WHERE h.employment_id=(r->>'employment_id')::bigint AND h.period=(r->>'period')::date AND h.current_report_id IS NOT NULL));
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未定义的排班考勤审批类型';END IF;
 RETURN md5(jsonb_build_object('type',p_type,'request',r,'dependencies',deps)::text);
END;$$;
CREATE FUNCTION fn_ty_tw_execution_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_workflow_instance;r jsonb;people jsonb;
BEGIN
 SELECT*INTO i FROM public.ty_workflow_instance WHERE id=NEW.instance_id;
 IF NEW.subject_type='time_change'THEN SELECT to_jsonb(x),x.participant_person_ids INTO r,people FROM public.ty_time_change_request x WHERE id=NEW.subject_id;
 ELSE SELECT to_jsonb(x),jsonb_build_array(x.person_id::text)INTO r,people FROM public.ty_time_punch_correction_request x WHERE id=NEW.subject_id;END IF;
 IF i.id IS NULL OR r IS NULL OR r->>'status'<>'pending'OR(r->>'revision')::integer<>NEW.source_revision OR(r->>'group_id')::bigint<>NEW.group_id OR i.subject_type<>NEW.subject_type OR i.subject_id<>NEW.subject_id OR i.source_hash<>NEW.source_hash OR NEW.source_hash<>public.fn_ty_tw_source_hash(NEW.subject_type,NEW.subject_id)OR i.group_id<>NEW.group_id OR i.company_id IS DISTINCT FROM NEW.company_id OR i.status<>(CASE WHEN NEW.outcome THEN'approved'ELSE'rejected'END) OR i.business_state<>'pending'OR i.last_approver_id<>NEW.approved_by OR i.applicant_id<>NEW.submitted_by OR(r->>'created_by')::bigint<>NEW.original_created_by OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.original_created_by)OR public.fn_ty_hr_same_human(NEW.approved_by,NEW.submitted_by)OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(people)p WHERE public.fn_ty_hr_actor_is_person(NEW.approved_by,NEW.group_id,p::bigint))OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_task WHERE instance_id=i.id AND approver_id=NEW.approved_by AND status=CASE WHEN NEW.outcome THEN'approved'ELSE'rejected'END AND acted_at IS NOT NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班考勤实际办理必须来自当前确切来源及真实独立审批凭证';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_tw_execution_guard BEFORE INSERT ON ty_tw_execution FOR EACH ROW EXECUTE FUNCTION fn_ty_tw_execution_guard();
CREATE FUNCTION fn_ty_tw_company_ids(p_type text,p_id bigint)RETURNS bigint[]LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE r jsonb;result bigint[];
BEGIN
 IF p_type='time_change'THEN SELECT to_jsonb(x)INTO r FROM public.ty_time_change_request x WHERE id=p_id;
 SELECT array_agg(DISTINCT company_id)INTO result FROM(SELECT(x->>'work_company_id')::bigint company_id FROM jsonb_array_elements((r->'before_data')||(r->'patches'))x UNION SELECT e.company_id FROM public.ty_employment e WHERE e.id IN(SELECT(x->>'employment_id')::bigint FROM jsonb_array_elements((r->'before_data')||(r->'patches'))x))c;
 ELSE SELECT ARRAY[x.company_id,e.company_id]INTO result FROM public.ty_time_punch_correction_request x JOIN public.ty_employment e ON e.id=x.employment_id WHERE x.id=p_id;END IF;RETURN result;
END;$$;
CREATE FUNCTION fn_ty_tw_decision_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE subject text;v_kind text;bound boolean;
BEGIN
 IF OLD.status<>'pending'OR NEW.status NOT IN('approved','rejected')THEN RETURN NEW;END IF;
 subject:=CASE WHEN TG_TABLE_NAME='ty_time_change_request'THEN'time_change'ELSE'time_punch_correction'END;v_kind:=CASE WHEN subject='time_change'THEN to_jsonb(NEW)->>'kind'ELSE'punch_correction'END;
 SELECT EXISTS(SELECT 1 FROM public.ty_workflow_binding b WHERE b.group_id=NEW.group_id AND b.business_type=subject AND(b.company_id IS NULL OR b.company_id=ANY(public.fn_ty_tw_company_ids(subject,NEW.id)))AND b.status='active'AND b.valid_from<=now()AND(b.valid_to IS NULL OR now()<b.valid_to)AND(b.kind IS NULL OR b.kind=v_kind))OR EXISTS(SELECT 1 FROM public.ty_workflow_instance i WHERE i.subject_type=subject AND i.subject_id=NEW.id AND i.status IN('running','blocked','approved')AND i.business_state IN('pending','blocked'))INTO bound;
 IF bound AND NOT EXISTS(SELECT 1 FROM public.ty_tw_execution e WHERE e.subject_type=subject AND e.subject_id=NEW.id AND e.outcome=(NEW.status='approved')AND e.approved_by=NEW.decided_by AND e.source_revision=OLD.revision AND e.source_hash=public.fn_ty_tw_source_hash(subject,NEW.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='此调班或补卡事项已绑定审批，须经原流程核准并显式实际办理';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_tw_change_bound BEFORE UPDATE ON ty_time_change_request FOR EACH ROW EXECUTE FUNCTION fn_ty_tw_decision_guard();
CREATE TRIGGER ty_tw_correction_bound BEFORE UPDATE ON ty_time_punch_correction_request FOR EACH ROW EXECUTE FUNCTION fn_ty_tw_decision_guard();
CREATE FUNCTION fn_ty_tw_completed_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r jsonb;i public.ty_workflow_instance;
BEGIN
 IF NEW.subject_type='time_change'THEN SELECT to_jsonb(x)INTO r FROM public.ty_time_change_request x WHERE id=NEW.subject_id;ELSE SELECT to_jsonb(x)INTO r FROM public.ty_time_punch_correction_request x WHERE id=NEW.subject_id;END IF;SELECT*INTO i FROM public.ty_workflow_instance WHERE id=NEW.instance_id;
 IF r->>'status'<>(CASE WHEN NEW.outcome THEN'approved'ELSE'rejected'END) OR(r->>'decided_by')::bigint<>NEW.approved_by OR i.business_state<>'applied'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际办理凭证与原生结果、审批办结必须在同一事务完成';END IF;RETURN NEW;
END;$$;
CREATE CONSTRAINT TRIGGER ty_tw_completed_guard AFTER INSERT ON ty_tw_execution DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_tw_completed_guard();
